const Q = [{"topic": "Agricultural biotechnology", "sn": 1, "text": "Which of the following is the primary goal of micropropagation in modern agriculture?", "opts": ["To introduce wild traits into domesticated crops", "To produce large numbers of genetically identical, disease-free plants rapidly", "To reduce the amount of water required by cereal crops", "To completely eliminate the need for chemical fertilizers"], "ans": "B", "steps": [["Micropropagation is tissue culture of tiny plant pieces", "it gives many identical, disease-free plants quickly"], ["{{A}} is breeding or GMO work; {{C,D}} are not goals of tissue culture", "reject, so {{B}}"]], "note": "", "n": 1, "src": "Unit 1 (Applications of Biology), Q1"}, {"topic": "Agricultural biotechnology", "sn": 2, "text": "How do chemical fertilizers structurally differ from organic fertilizers?", "opts": ["Chemical fertilizers contain complex organic matrices that release nutrients slowly.", "Chemical fertilizers supply purified, highly concentrated inorganic mineral ions for rapid uptake.", "Chemical fertilizers rely exclusively on live bacterial cultures to fix atmospheric nitrogen.", "Chemical fertilizers do not alter the soil pH or salinity regardless of application volume."], "ans": "B", "steps": [["Chemical fertilizers are purified inorganic ions (nitrate, phosphate, potassium)", "they dissolve and are taken up fast"], ["{{A}} describes organic fertilizer, {{C}} describes biofertilizer, {{D}} is false (heavy use changes pH and salinity)", "reject, so {{B}}"]], "note": "", "n": 2, "src": "Unit 1 (Applications of Biology), Q2"}, {"topic": "Agricultural biotechnology", "sn": 3, "text": "In integrated pest management (IPM), which action represents a biological control method?", "opts": ["Spraying synthetic organophosphate insecticides over a wide canopy area.", "Constructing physical netting and traps to catch migratory locusts.", "Introducing a specific predatory wasp species to parasitize aphid populations.", "Using heavy machinery to till the soil and destroy weed seed banks."], "ans": "C", "steps": [["Biological control means using living natural enemies", "a parasitic wasp attacking aphids fits"], ["{{A}} is chemical, {{B}} is physical, {{D}} is cultural or mechanical", "reject, so {{C}}"]], "note": "", "n": 3, "src": "Unit 1 (Applications of Biology), Q3"}, {"topic": "Agricultural biotechnology", "sn": 4, "text": "Which crop is a classic example of a Genetically Modified Organism (GMO) engineered to express an insecticidal protein from Bacillus thuringiensis?", "opts": ["Golden Rice", "Bt Cotton", "Flavr Savr Tomato", "Rainbow Papaya"], "ans": "B", "steps": [["Bt stands for Bacillus thuringiensis, whose toxin gene kills caterpillar pests", "Bt cotton carries it"], ["Golden Rice adds vitamin A, Flavr Savr delays softening, Rainbow Papaya resists ringspot virus", "reject, so {{B}}"]], "note": "", "n": 4, "src": "Unit 1 (Applications of Biology), Q4"}, {"topic": "Agricultural biotechnology", "sn": 5, "text": "What is the main ecological advantage of using organic farming practices over intensive conventional agriculture?", "opts": ["Immediate and drastic increase in short-term crop yields", "Complete eradication of all insect and weed species in the local biome", "Preservation of soil structure, enhancement of biodiversity, and reduced chemical runoff", "Lower initial labor and management requirements for large-scale production"], "ans": "C", "steps": [["Organic farming avoids heavy synthetic inputs", "soil structure and biodiversity are protected and runoff drops"], ["{{A,D}} are false for organic farming, and {{B}} is not a goal", "reject, so {{C}}"]], "note": "", "n": 5, "src": "Unit 1 (Applications of Biology), Q5"}, {"topic": "Agricultural biotechnology", "sn": 6, "text": "Hydroponics is a cultivation methodology that grows plants without which traditional medium?", "opts": ["Water", "Soil", "Sunlight", "Oxygen"], "ans": "B", "steps": [["Hydroponics grows plants in a water-based nutrient solution", "no soil is used"], ["Plants still need water, light and oxygen at the roots", "reject, so {{B}}"]], "note": "", "n": 6, "src": "Unit 1 (Applications of Biology), Q6"}, {"topic": "Agricultural biotechnology", "sn": 7, "text": "Which plant hormone is commonly applied in commercial agriculture to promote uniform fruit ripening during transport?", "opts": ["Auxin", "Gibberellin", "Abscisic Acid", "Ethylene"], "ans": "D", "steps": [["Ethylene is the gaseous ripening hormone", "it is applied to ripen fruit evenly after transport"], ["Auxin and gibberellin promote growth, abscisic acid causes dormancy and stress responses", "reject, so {{D}}"]], "note": "", "n": 7, "src": "Unit 1 (Applications of Biology), Q7"}, {"topic": "Agricultural biotechnology", "sn": 8, "text": "What role do mycorrhizal fungi play when associated with the roots of agricultural crops?", "opts": ["They fix atmospheric nitrogen directly into ammonium ions.", "They physically protect the leaves from airborne viral pathogens.", "They vastly expand the root surface area to improve phosphorus and water absorption.", "They synthesize chlorophyll molecules to accelerate the light-independent reactions."], "ans": "C", "steps": [["Mycorrhiza is a fungus-root partnership", "the hyphae widen the absorbing area for phosphorus and water"], ["Nitrogen fixers are bacteria, fungi make no chlorophyll, and roots are not leaves", "reject, so {{C}}"]], "note": "", "n": 8, "src": "Unit 1 (Applications of Biology), Q8"}, {"topic": "Agricultural biotechnology", "sn": 9, "text": "Selective breeding differs from genetic engineering primarily because selective breeding:", "opts": ["Introduces foreign DNA from entirely different biological kingdoms.", "Relies on the natural reproductive processes and existing genetic variation within a species.", "Is completed within a single generation in a laboratory environment.", "Does not change the allele frequencies of the target population over time."], "ans": "B", "steps": [["Selective breeding chooses parents with the wanted traits", "it uses variation already in the species, over many generations"], ["{{A}} is genetic engineering, {{C}} is false (it is slow), {{D}} is false (allele frequencies do shift)", "reject, so {{B}}"]], "note": "", "n": 9, "src": "Unit 1 (Applications of Biology), Q9"}, {"topic": "Agricultural biotechnology", "sn": 10, "text": "Which of the following practices is specifically used to prevent soil erosion and maintain nutrient profiles on sloped agricultural land?", "opts": ["Monoculture farming", "Terrace farming", "Broad-spectrum chemical fumigation", "Overhead flood irrigation"], "ans": "B", "steps": [["Terraces turn a slope into steps", "runoff slows, soil and nutrients stay in place"], ["Monoculture, fumigation and flooding raise erosion or damage the soil", "reject, so {{B}}"]], "note": "", "n": 10, "src": "Unit 1 (Applications of Biology), Q10"}, {"topic": "Agricultural biotechnology", "sn": 11, "text": "What is the primary biological mechanism behind crop rotation?", "opts": ["Forcing crops to adapt to different structural soil densities each year.", "Interrupting the life cycles of host-specific pests and naturally balancing soil nutrients.", "Increasing the rate of genetic mutations within the planted crops.", "Maximizing the accumulation of toxic heavy metals in the topsoil."], "ans": "B", "steps": [["A different crop each season starves host-specific pests", "it also balances nutrients (legumes add nitrogen)"], ["{{A,C,D}} are not effects of rotation", "reject, so {{B}}"]], "note": "", "n": 11, "src": "Unit 1 (Applications of Biology), Q11"}, {"topic": "Agricultural biotechnology", "sn": 12, "text": "Green manure refers to:", "opts": ["Artificial chemical dyes added to liquid fertilizers to track distribution.", "Cover crops that are plowed back into the soil to decompose and enrich nutrient content.", "Decomposed animal waste collected exclusively from factory livestock farms.", "Algal blooms harvested from eutrophic lakes to be used as topsoil layers."], "ans": "B", "steps": [["Green manure is a growing crop ploughed back in", "it decomposes and enriches the soil"], ["{{A}} is a dye, {{C}} is animal manure, {{D}} is algal harvest", "reject, so {{B}}"]], "note": "", "n": 12, "src": "Unit 1 (Applications of Biology), Q12"}, {"topic": "Agricultural biotechnology", "sn": 13, "text": "Which bacterial genus is widely utilized in agricultural biotechnology as a vector to transfer foreign genes into dicotyledonous plants?", "opts": ["Escherichia", "Agrobacterium", "Rhizobium", "Lactobacillus"], "ans": "B", "steps": [["Agrobacterium tumefaciens naturally moves its T-DNA into plant cells", "it is used as a gene vector, mainly in dicots"], ["Escherichia is a lab host, Rhizobium fixes nitrogen, Lactobacillus makes lactic acid", "reject, so {{B}}"]], "note": "", "n": 13, "src": "Unit 1 (Applications of Biology), Q13"}, {"topic": "Agricultural biotechnology", "sn": 14, "text": "The term \"marker-assisted selection\" (MAS) in modern agriculture helps breeders by:", "opts": ["Directly modifying the nucleotide sequence of an elite line's genome.", "Using molecular markers linked to desirable traits to select individuals without waiting for adult phenotype expression", "Painting visual indicators onto plant stems to monitor their physical height.", "Synthesizing artificial chromosomes in test tubes for direct injection into plant stems."], "ans": "B", "steps": [["MAS uses DNA markers that travel with a trait gene", "breeders can pick seedlings early, before the trait shows"], ["{{A}} is genome editing; {{C,D}} are not MAS", "reject, so {{B}}"]], "note": "", "n": 14, "src": "Unit 1 (Applications of Biology), Q14"}, {"topic": "Agricultural biotechnology", "sn": 15, "text": "Which of the following is an environmental risk associated with the overuse of synthetic nitrogenous fertilizers?", "opts": ["The complete deoxygenation of the upper atmosphere.", "Eutrophication of nearby aquatic ecosystems due to nutrient leaching.", "Massive increases in the thickness of the soil's organic horizon.", "Rapid evolution of plants into non-photosynthetic heterotrophs."], "ans": "B", "steps": [["Excess nitrate and phosphate wash into water", "algae bloom, then oxygen falls (eutrophication)"], ["{{A,C,D}} are not real consequences", "reject, so {{B}}"]], "note": "", "n": 15, "src": "Unit 1 (Applications of Biology), Q15"}, {"topic": "Medical biotechnology", "sn": 16, "text": "Monoclonal antibodies are highly valued in modern medicine because they:", "opts": ["Can non-specifically destroy any foreign cell or virus they encounter.", "Are produced by a single clone of hybridoma cells and bind to one specific epitope on an antigen.", "Can permanently integrate into the patient's germline DNA to provide lifelong immunity.", "Are synthetic chemical compounds that function independently of biological systems."], "ans": "B", "steps": [["Monoclonal means one clone of hybridoma cells", "every antibody binds the same single epitope"], ["{{A}} contradicts \"specific\"; {{C,D}} are false", "reject, so {{B}}"]], "note": "", "n": 16, "src": "Unit 1 (Applications of Biology), Q16"}, {"topic": "Medical biotechnology", "sn": 17, "text": "What is the therapeutic mechanism of action of recombinant human insulin produced via biotechnology?", "opts": ["It binds to glucose molecules directly in the bloodstream to destroy them.", "It binds to specific cell surface receptors, triggering the upregulation of GLUT transporters to lower blood glucose.", "It stimulates the alpha cells of the pancreas to secrete high volumes of glucagon.", "It alters the genetic code of liver cells so they stop storing glycogen."], "ans": "B", "steps": [["Insulin binds a receptor on the cell surface", "cells add GLUT transporters and take in glucose, so blood sugar falls"], ["Glucagon raises blood sugar; {{A,D}} are not what insulin does", "reject, so {{B}}"]], "note": "", "n": 17, "src": "Unit 1 (Applications of Biology), Q17"}, {"topic": "Medical biotechnology", "sn": 18, "text": "Which of the following describes a \"live-attenuated\" vaccine?", "opts": ["A vaccine containing only isolated, purified protein subunits of a virus.", "A vaccine containing a completely dead pathogen inactivated by heat or chemicals.", "A vaccine containing a weakened version of the living pathogen that replicates poorly but stimulates a strong immune response.", "A vaccine consisting of naked plasmid DNA encoding a bacterial toxin."], "ans": "C", "steps": [["Live-attenuated means weakened but still alive", "it multiplies a little and gives a strong response"], ["{{A}} is a subunit vaccine, {{B}} is inactivated, {{D}} is a DNA vaccine", "reject, so {{C}}"]], "note": "", "n": 18, "src": "Unit 1 (Applications of Biology), Q18"}, {"topic": "Medical biotechnology", "sn": 19, "text": "Gene therapy aims to treat genetic disorders by:", "opts": ["Prescribing specific synthetic drugs that mimic missing structural proteins.", "Delivering a functional copy of a gene into a patient's cells to replace or supplement a defective gene.", "Using targeted X-ray radiation to mutate abnormal proteins back into normal configurations.", "Altering the global environmental conditions to suppress the expression of all inherited traits."], "ans": "B", "steps": [["Gene therapy supplies a working copy of the gene", "it replaces or supplements the faulty one"], ["Drugs, radiation and environment change do not insert genes", "reject, so {{B}}"]], "note": "", "n": 19, "src": "Unit 1 (Applications of Biology), Q19"}, {"topic": "Medical biotechnology", "sn": 20, "text": "Antibiotic resistance in bacteria frequently spreads through the horizontal transfer of which structural genetic element?", "opts": ["Genomic exons", "Plasmids", "Histone proteins", "Mitochondrial DNA"], "ans": "B", "steps": [["Plasmids carry resistance genes and pass between bacteria (conjugation)", "this is the main route of spread"], ["Exons and histones belong to eukaryotes; mitochondrial DNA is not transferred between bacteria", "reject, so {{B}}"]], "note": "", "n": 20, "src": "Unit 1 (Applications of Biology), Q20"}, {"topic": "Medical biotechnology", "sn": 21, "text": "The technique known as CRISPR-Cas9 is revolutionized in medicine primarily as a tool for:", "opts": ["Amplifying tiny quantities of DNA during forensic investigations.", "Precise, targeted editing of specific nucleotide sequences within living genomes.", "Separating protein fragments based on their electrical charge and molecular weight.", "Measuring the rate of cellular respiration in real-time."], "ans": "B", "steps": [["A guide RNA leads the Cas9 enzyme to one DNA sequence, where it cuts", "this allows precise genome editing"], ["{{A}} is PCR, {{C}} is electrophoresis, {{D}} is respirometry", "reject, so {{B}}"]], "note": "", "n": 21, "src": "Unit 1 (Applications of Biology), Q21"}, {"topic": "Medical biotechnology", "sn": 22, "text": "What is the primary role of a vector (such as a modified adenovirus) in gene therapy applications?", "opts": ["To manufacture the therapeutic protein in a large external bioreactor.", "To physically transport and insert the therapeutic genetic material into the target human cells.", "To neutralize the patient's active immune system so it does not attack the medication.", "To act as a diagnostic marker that glows under ultraviolet light."], "ans": "B", "steps": [["A vector is a carrier", "it delivers the therapeutic gene into target cells"], ["{{A,C,D}} are not vector roles", "reject, so {{B}}"]], "note": "", "n": 22, "src": "Unit 1 (Applications of Biology), Q22"}, {"topic": "Medical biotechnology", "sn": 23, "text": "Pharmacogenomics is an emerging medical field that studies how:", "opts": ["Viruses evolve resistance to antiviral drugs over successive generations.", "An individual's genetic makeup affects their specific physiological response to drugs.", "Large pharmaceutical companies manage the financial distribution of vaccines.", "Soil microbes synthesize novel chemical compounds with therapeutic properties."], "ans": "B", "steps": [["Pharmaco = drugs, genomics = genes", "it studies how your genes change your drug response"], ["{{A}} is resistance evolution, {{C}} is finance, {{D}} is natural-product discovery", "reject, so {{B}}"]], "note": "", "n": 23, "src": "Unit 1 (Applications of Biology), Q23"}, {"topic": "Medical biotechnology", "sn": 24, "text": "Which diagnostic technique relies heavily on the Polymerase Chain Reaction (PCR)?", "opts": ["Viewing the detailed surface topology of a bacterial cell structure.", "Measuring the blood pressure variations across the major systemic arteries.", "Detecting and amplifying minute quantities of viral nucleic acids in a patient's blood sample.", "Separating serum proteins using simple gravity-fed filtration columns."], "ans": "C", "steps": [["PCR copies tiny amounts of DNA or RNA", "it detects viral nucleic acid in blood"], ["{{A,B,D}} do not amplify nucleic acid", "reject, so {{C}}"]], "note": "", "n": 24, "src": "Unit 1 (Applications of Biology), Q24"}, {"topic": "Medical biotechnology", "sn": 25, "text": "An ELISA (Enzyme-Linked Immunosorbent Assay) test uses which primary biological interaction to detect diseases or hormones?", "opts": ["Enzyme-substrate specificity combined with highly specific antigen-antibody binding.", "The natural pairing of complementary RNA and DNA strands under heat.", "The migration of positively charged ions toward a negative electrode grid.", "The competitive inhibition of cellular respiration pathways within blood cells."], "ans": "A", "steps": [["ELISA links an enzyme to an antibody", "antigen-antibody binding then gives a colour signal from the enzyme"], ["{{B}} is hybridization, {{C}} is electrophoresis, {{D}} is unrelated", "reject, so {{A}}"]], "note": "", "n": 25, "src": "Unit 1 (Applications of Biology), Q25"}, {"topic": "Medical biotechnology", "sn": 26, "text": "Therapeutic cloning is fundamentally designed to produce:", "opts": ["Fully formed, identical adult organisms for organ harvesting.", "Embryonic stem cells that are genetically matched to a patient for tissue regeneration.", "Synthetic chemical polymers that mimic the structure of human skin.", "Large quantities of industrial enzymes for use in environmental cleanup projects."], "ans": "B", "steps": [["Therapeutic cloning makes embryonic stem cells with the patient's own DNA", "they are used to regenerate tissue without rejection"], ["{{A}} is reproductive cloning; {{C,D}} are unrelated", "reject, so {{B}}"]], "note": "", "n": 26, "src": "Unit 1 (Applications of Biology), Q26"}, {"topic": "Medical biotechnology", "sn": 27, "text": "What makes stem cells uniquely valuable in regenerative medicine?", "opts": ["They are completely immune to all known bacterial and viral infections.", "They lack a nucleus, allowing them to fit into tight capillary beds without clotting.", "They are unspecialized cells capable of self-renewal and differentiating into various mature cell types.", "They undergo rapid meiosis to create diverse haploid cell lineages in somatic organs."], "ans": "C", "steps": [["Stem cells are unspecialized", "they self-renew and can become many mature cell types"], ["{{A,B,D}} are false (they have a nucleus, are not immune, and do not undergo meiosis in somatic organs)", "reject, so {{C}}"]], "note": "In the source, option {{D}} is printed on the same line as option {{C}}; it is separated here.", "n": 27, "src": "Unit 1 (Applications of Biology), Q27"}, {"topic": "Medical biotechnology", "sn": 28, "text": "Which of the following is a classic example of an auto-immune disease?", "opts": ["Type 1 Diabetes Mellitus", "Hemophilia A", "Iron Deficiency Anemia", "Malaria"], "ans": "A", "steps": [["Autoimmune means the immune system attacks the body's own tissue", "in type 1 diabetes it destroys the pancreatic beta cells"], ["Hemophilia A is a genetic clotting defect, iron deficiency is nutritional, malaria is a parasite", "reject, so {{A}}"]], "note": "", "n": 28, "src": "Unit 1 (Applications of Biology), Q28"}, {"topic": "Medical biotechnology", "sn": 30, "text": "What is the primary ethical concern surrounding germline gene therapy compared to somatic gene therapy?", "opts": ["Germline mutations are temporary and disappear when the patient stops taking the medication.", "Germline modifications alter the DNA of reproductive cells, passing the genetic changes down to all future generations.", "Germline therapy requires the complete destruction of the patient's entire skeletal system.", "Somatic gene therapy is highly infectious and can easily spread to health workers."], "ans": "B", "steps": [["Germline therapy changes sperm, eggs or embryos", "the change is inherited by all future generations, which is the ethical worry"], ["{{A,C,D}} are false", "reject, so {{B}}"]], "note": "", "n": 29, "src": "Unit 1 (Applications of Biology), Q30"}, {"topic": "Industrial biotechnology and DNA tools", "sn": 31, "text": "In industrial fermentation, why is it critical to constantly monitor and regulate the temperature inside a bioreactor?", "opts": ["To prevent the structural DNA of the microbes from permanently transforming into RNA.", "To maintain optimal kinetic conditions for microbial enzymes and prevent thermal denaturation.", "To ensure that the fluid medium changes color at precise economic intervals.", "To force the microorganisms to enter a permanent state of dormancy."], "ans": "B", "steps": [["Enzymes work best in a narrow temperature range", "too hot denatures them, too cold slows them"], ["{{A,C,D}} are not real reasons", "reject, so {{B}}"]], "note": "", "n": 30, "src": "Unit 1 (Applications of Biology), Q31"}, {"topic": "Industrial biotechnology and DNA tools", "sn": 32, "text": "Which organism is predominantly used in the baking and brewing industries to carry out alcoholic fermentation?", "opts": ["Lactobacillus bulgaricus", "Saccharomyces cerevisiae", "Escherichia coli", "Aspergillus niger"], "ans": "B", "steps": [["Yeast ferments sugar into ethanol and CO2", "CO2 raises dough and ethanol makes beer"], ["Lactobacillus makes lactic acid, E. coli is a lab bacterium, Aspergillus niger makes citric acid", "reject, so {{B}}"]], "note": "", "n": 31, "src": "Unit 1 (Applications of Biology), Q32"}, {"topic": "Industrial biotechnology and DNA tools", "sn": 33, "text": "Bioremediation refers to the industrial process of using living organisms to:", "opts": ["Mass-produce synthetic plastic polymers for consumer packaging.", "Clean up, break down, or neutralize environmental pollutants and toxic waste from contaminated sites.", "Directly generate high-voltage electricity for municipal grids.", "Synthesize structural proteins to build biomedical prosthetics."], "ans": "B", "steps": [["Bio = living, remediate = to fix", "organisms break down or neutralize pollutants"], ["{{A,C,D}} are unrelated uses", "reject, so {{B}}"]], "note": "", "n": 32, "src": "Unit 1 (Applications of Biology), Q33"}, {"topic": "Industrial biotechnology and DNA tools", "sn": 34, "text": "What are the primary metabolic end-products of anaerobic respiration in lactic acid bacteria during yogurt production?", "opts": ["Ethanol and Carbon Dioxide", "Lactic Acid and Hydrogen Gas", "Lactic Acid only (which lowers pH and coagulates milk proteins)", "Methane and Water"], "ans": "C", "steps": [["Lactic acid bacteria ferment lactose to lactic acid", "the acid lowers pH and curdles the milk protein"], ["Ethanol and CO2 come from yeast; hydrogen, methane and water are not the products here", "reject, so {{C}}"]], "note": "Strictly, this is fermentation, not anaerobic respiration.", "n": 33, "src": "Unit 1 (Applications of Biology), Q34"}, {"topic": "Industrial biotechnology and DNA tools", "sn": 35, "text": "During down-stream processing in industrial biotechnology, what takes place?", "opts": ["The formulation of the raw media and initial inoculation of the target strain.", "The purification, isolation, and formulation of the final desired biological product from the cell culture.", "The screening of wild microbial isolates using selective agar plates.", "The deliberate induction of random genetic mutations using UV radiation lamps"], "ans": "B", "steps": [["Downstream means after fermentation", "the product is purified, isolated and formulated"], ["{{A}} is upstream work, {{C}} is screening, {{D}} is mutagenesis", "reject, so {{B}}"]], "note": "", "n": 34, "src": "Unit 1 (Applications of Biology), Q35"}, {"topic": "Industrial biotechnology and DNA tools", "sn": 36, "text": "Restriction endonucleases are crucial molecular tools in biotechnology because they:", "opts": ["Repair broken phosphodiester bonds along the sugar-phosphate backbone.", "Cut double-stranded DNA molecules at specific, highly defined palindromic nucleotide sequences.", "Unwind the DNA double helix during the replication phase in a bioreactor.", "Translate messenger RNA strands directly into functional structural proteins."], "ans": "B", "steps": [["Restriction enzymes recognise palindromic sequences", "they cut DNA there (molecular scissors)"], ["{{A}} is ligase, {{C}} is helicase, {{D}} is the ribosome", "reject, so {{B}}"]], "note": "", "n": 35, "src": "Unit 1 (Applications of Biology), Q36"}, {"topic": "Industrial biotechnology and DNA tools", "sn": 37, "text": "What is \"Single-Cell Protein\" (SCP)?", "opts": ["A specialized structural protein found exclusively in the human nervous system.", "Edible protein extracts derived from pure microbial cultures (algae, fungi, or bacteria) used as food supplements.", "The single, large protein molecule that forms the cell wall of Gram-negative bacteria.", "A type of synthetic meat produced entirely using advanced chemical polymer chains."], "ans": "B", "steps": [["SCP is protein-rich biomass grown from microbes", "algae, yeast, fungi or bacteria used as food or feed"], ["{{A,C,D}} are not what the term means", "reject, so {{B}}"]], "note": "", "n": 36, "src": "Unit 1 (Applications of Biology), Q37"}, {"topic": "Industrial biotechnology and DNA tools", "sn": 38, "text": "The enzyme chymosin (rennet), widely used in the commercial cheese-making industry to curdle milk, is now primarily produced by:", "opts": ["Extracting it from the stomach linings of slaughtered newborn calves.", "Genetically modified microorganisms containing the cloned mammalian chymosin gene.", "Synthesizing it step-by-step using heavy industrial petrochemical reactors.", "Harvesting it from specific marine kelp forests."], "ans": "B", "steps": [["The calf chymosin gene was cloned into microbes", "they make rennet cheaply with no slaughter needed"], ["{{A}} is the old method; {{C,D}} are not used", "reject, so {{B}}"]], "note": "", "n": 37, "src": "Unit 1 (Applications of Biology), Q38"}, {"topic": "Industrial biotechnology and DNA tools", "sn": 39, "text": "What is the function of the enzyme DNA Ligase in recombinant DNA technology?", "opts": ["It acts as a pair of molecular scissors to slice open targeted plasmids.", "It covalently joins two separate DNA fragments together by catalyzing the formation of phosphodiester bonds.", "It transcribes viral RNA back into stable complementary DNA.", "It breaks hydrogen bonds between matching purine and pyrimidine bases."], "ans": "B", "steps": [["Ligase is the molecular glue", "it seals DNA fragments by forming phosphodiester bonds"], ["{{A}} is a restriction enzyme, {{C}} is reverse transcriptase, {{D}} is helicase", "reject, so {{B}}"]], "note": "", "n": 38, "src": "Unit 1 (Applications of Biology), Q39"}, {"topic": "Industrial biotechnology and DNA tools", "sn": 40, "text": "Gel electrophoresis separates DNA fragments principally based on which two physical properties?", "opts": ["Molecular weight (size) and electrical charge", "Chemical solubility and boiling point", "The ratio of adenine to thymine bases", "Viscosity and optical reflectivity"], "ans": "A", "steps": [["DNA is negatively charged, so it moves toward the positive electrode", "the gel sieves fragments by size, small ones move farther"], ["{{B,C,D}} are not properties used", "reject, so {{A}}"]], "note": "DNA's charge-to-mass ratio is nearly constant, so size does the actual separating; {{A}} is the intended answer.", "n": 39, "src": "Unit 1 (Applications of Biology), Q40"}, {"topic": "Industrial biotechnology and DNA tools", "sn": 41, "text": "Which of the following is considered a primary metabolite in industrial microbiology?", "opts": ["Penicillin, produced during the stationary phase of growth.", "Ethanol, produced continuously during the active logarithmic growth phase.", "A specific structural toxin generated only under extreme environmental stress.", "An advanced secondary pigment used for self-defense by mature molds."], "ans": "B", "steps": [["Primary metabolites are made during active (log) growth", "ethanol is made continuously then"], ["Penicillin, stress toxins and defence pigments are secondary metabolites", "reject, so {{B}}"]], "note": "", "n": 40, "src": "Unit 1 (Applications of Biology), Q41"}, {"topic": "Industrial biotechnology and DNA tools", "sn": 42, "text": "The term \"Pasteurization\" describes a food preservation process that involves:", "opts": ["Adding heavy amounts of chemical preservatives and salt to completely sterilize food forever.", "Heating liquids to a specific temperature for a defined time to destroy pathogenic microbes without ruining food quality.", "Storing food products in absolute vacuum chambers at sub-zero temperatures.", "Exposing food items to high doses of ionizing gamma radiation."], "ans": "B", "steps": [["Pasteurization is controlled mild heating", "it kills pathogens but keeps the food quality"], ["{{A}} is chemical preservation, {{C}} is freezing or vacuum, {{D}} is irradiation", "reject, so {{B}}"]], "note": "", "n": 41, "src": "Unit 1 (Applications of Biology), Q42"}, {"topic": "Industrial biotechnology and DNA tools", "sn": 43, "text": "Why are immobilised enzymes often preferred over free enzymes in industrial food processing?", "opts": ["Immobilised enzymes completely change their substrate specificity to work on any molecule.", "They can be easily recovered and reused, leading to lower operating costs and contamination-free products.", "They function at much higher speeds because they are structurally unstable.", "They do not require any specific temperature or pH regulation to operate."], "ans": "B", "steps": [["Immobilised enzymes are fixed to a support", "they can be recovered and reused, and they do not contaminate the product"], ["{{A,C,D}} are false", "reject, so {{B}}"]], "note": "", "n": 42, "src": "Unit 1 (Applications of Biology), Q43"}, {"topic": "Industrial biotechnology and DNA tools", "sn": 44, "text": "Which biological vector is naturally a small, circular, double-stranded extra-chromosomal DNA molecule found in bacteria?", "opts": ["Bacteriophage", "Plasmid", "Cosmid", "Intron"], "ans": "B", "steps": [["Small circular extra-chromosomal DNA in bacteria", "that describes a plasmid"], ["A bacteriophage is a virus, a cosmid is an engineered hybrid, an intron is part of a gene", "reject, so {{B}}"]], "note": "", "n": 43, "src": "Unit 1 (Applications of Biology), Q44"}, {"topic": "Industrial biotechnology and DNA tools", "sn": 45, "text": "What is the primary industrial application of the enzyme amylase?", "opts": ["Breaking down structural cellulose fibers to make heavy writing paper.", "Hydrolyzing complex starch molecules into simpler fermentable sugars in food and brewing industries.", "Coagulating blood proteins for medical bandages.", "Synthesizing long-chain fatty acids for cosmetic soap manufacturing."], "ans": "B", "steps": [["Amylase digests starch", "it releases sugars for baking, brewing and syrups"], ["{{A}} is cellulase, {{C,D}} are unrelated", "reject, so {{B}}"]], "note": "", "n": 44, "src": "Unit 1 (Applications of Biology), Q45"}, {"topic": "Core concepts, genomics, ethics and biosafety", "sn": 46, "text": "The use of biological processes, organisms, or systems to manufacture products intended to improve the quality of human life is the definition of:", "opts": ["Ecology", "Biotechnology", "Anatomy", "Paleontology"], "ans": "B", "steps": [["Using living systems to make useful products", "that is the definition of biotechnology"], ["Ecology, anatomy and paleontology are studies, not production methods", "reject, so {{B}}"]], "note": "", "n": 45, "src": "Unit 1 (Applications of Biology), Q46"}, {"topic": "Core concepts, genomics, ethics and biosafety", "sn": 47, "text": "Bioethics is a vital field accompanying modern biology because it:", "opts": ["Dictates the exact monetary value of biological patents and products.", "Establishes ethical guidelines and moral boundaries for biological research and its medical/agricultural applications.", "Focuses exclusively on calculating the chemical mathematical constants of metabolic pathways.", "Aims to ban all forms of scientific research involving living organisms."], "ans": "B", "steps": [["Bioethics asks what is right in biological research and its uses", "it sets guidelines and limits"], ["{{A,C,D}} are not its purpose", "reject, so {{B}}"]], "note": "", "n": 46, "src": "Unit 1 (Applications of Biology), Q47"}, {"topic": "Core concepts, genomics, ethics and biosafety", "sn": 48, "text": "Which of the following represents a major concern regarding the release of genetically modified crops into wild environments?", "opts": ["The crops might stop performing cellular respiration entirely.", "Potential gene flow via cross-pollination to wild relatives, creating invasive \"superweeds.\"", "Rapid depletion of all atmospheric carbon dioxide due to excessive photosynthesis.", "Complete structural degradation of all global water molecules."], "ans": "B", "steps": [["Pollen can carry transgenes to wild relatives (gene flow)", "this can create herbicide-resistant superweeds"], ["{{A,C,D}} are not realistic", "reject, so {{B}}"]], "note": "", "n": 47, "src": "Unit 1 (Applications of Biology), Q48"}, {"topic": "Core concepts, genomics, ethics and biosafety", "sn": 49, "text": "A transgenic organism is defined as an organism that:", "opts": ["Contains a mutated gene that originated within its own immediate biological family.", "Contains a functional gene introduced into its genome from an entirely different species.", "Has lost its entire genomic sequence due to severe chemical radiation exposure.", "Reproduces strictly via asexual binary fission in laboratory environments."], "ans": "B", "steps": [["Trans = across", "it carries a working gene from another species"], ["{{A}} is ordinary mutation or breeding, {{C,D}} are not definitions", "reject, so {{B}}"]], "note": "", "n": 48, "src": "Unit 1 (Applications of Biology), Q49"}, {"topic": "Core concepts, genomics, ethics and biosafety", "sn": 50, "text": "Which area of biology deals with the naming, classifying, and grouping of organisms based on evolutionary relationships?", "opts": ["Taxonomy", "Physiology", "Histology", "Embryology"], "ans": "A", "steps": [["Naming and classifying organisms", "that is taxonomy"], ["Physiology is function, histology is tissues, embryology is development", "reject, so {{A}}"]], "note": "", "n": 49, "src": "Unit 1 (Applications of Biology), Q50"}, {"topic": "Core concepts, genomics, ethics and biosafety", "sn": 51, "text": "The comprehensive mapping and sequencing of all the genetic material within an organism's cell is known as:", "opts": ["Proteomics", "Transcriptomics", "Genomics", "Metabolomics"], "ans": "C", "steps": [["All the DNA of an organism = its genome", "mapping and sequencing it is genomics"], ["Proteomics studies proteins, transcriptomics RNA, metabolomics metabolites", "reject, so {{C}}"]], "note": "", "n": 50, "src": "Unit 1 (Applications of Biology), Q51"}, {"topic": "Core concepts, genomics, ethics and biosafety", "sn": 52, "text": "Which of the following is a direct application of biology in environmental conservation?", "opts": ["Maximizing the extraction of fossil fuels from deep subterranean reserves.", "Using indicator species to monitor ecosystem health and implementing captive breeding programs for endangered wildlife.", "Expanding concrete urban centers over native wetland habitats.", "Introducing broad-spectrum chemical toxins into native forests to eliminate undergrowth."], "ans": "B", "steps": [["Conservation protects species and habitats", "indicator species and captive breeding do exactly that"], ["{{A,C,D}} damage the environment", "reject, so {{B}}"]], "note": "", "n": 51, "src": "Unit 1 (Applications of Biology), Q52"}, {"topic": "Core concepts, genomics, ethics and biosafety", "sn": 53, "text": "What basic biological concept explains why high levels of salt or sugar act as highly effective food preservatives?", "opts": ["They induce rapid active transport of toxins into bacterial cells.", "They create a hypertonic environment, causing plasmolysis (dehydration) of contaminating microbial cells.", "They structurally alter the atmospheric oxygen levels surrounding the food container.", "They act as direct competitive inhibitors of all photosynthetic reactions."], "ans": "B", "steps": [["Salt or sugar makes the outside hypertonic", "water leaves microbes by osmosis (plasmolysis), so they cannot grow"], ["{{A,C,D}} are not the mechanism", "reject, so {{B}}"]], "note": "", "n": 52, "src": "Unit 1 (Applications of Biology), Q53"}, {"topic": "Core concepts, genomics, ethics and biosafety", "sn": 54, "text": "The study of how diseases emerge, spread, and are controlled within human populations is called:", "opts": ["Immunology", "Pathology", "Epidemiology", "Virology"], "ans": "C", "steps": [["Disease patterns in populations", "epidemiology"], ["Immunology is the immune system, pathology the disease process, virology viruses", "reject, so {{C}}"]], "note": "", "n": 53, "src": "Unit 1 (Applications of Biology), Q54"}, {"topic": "Core concepts, genomics, ethics and biosafety", "sn": 56, "text": "The use of living organisms, like specific hyperaccumulating plants, to extract and remove heavy metals from contaminated soils is called:", "opts": ["Phytoremediation", "Bioaugmentation", "Composting", "Leaching"], "ans": "A", "steps": [["Phyto = plant, remediation = cleaning", "plants that hyperaccumulate metals clean the soil"], ["Bioaugmentation adds microbes, composting makes humus, leaching washes nutrients out", "reject, so {{A}}"]], "note": "", "n": 54, "src": "Unit 1 (Applications of Biology), Q56"}, {"topic": "Core concepts, genomics, ethics and biosafety", "sn": 57, "text": "Which type of cell is formed by fusing a tumor cell (myeloma) with an antibody-producing B lymphocyte?", "opts": ["Stem cell", "Hybridoma cell", "Recombinant cell", "Plasmide cell"], "ans": "B", "steps": [["Myeloma cell (divides endlessly) + B cell (makes one antibody)", "the fused cell is a hybridoma"], ["Stem, recombinant and \"plasmide\" cells are different things", "reject, so {{B}}"]], "note": "", "n": 55, "src": "Unit 1 (Applications of Biology), Q57"}, {"topic": "Core concepts, genomics, ethics and biosafety", "sn": 58, "text": "What is the primary function of a thermal cycler in a molecular biology laboratory?", "opts": ["To maintain a constant freezing temperature for long-term enzyme storage.", "To rapidly cycle temperatures up and down to facilitate the steps of the Polymerase Chain Reaction (PCR).", "To provide constant mechanical agitation to industrial fermentation batches.", "To sterilize lab coats and surgical tools using superheated steam."], "ans": "B", "steps": [["PCR needs repeated heating and cooling (denature, anneal, extend)", "the thermal cycler automates that"], ["{{A}} is a freezer, {{C}} is a shaker, {{D}} is an autoclave", "reject, so {{B}}"]], "note": "", "n": 56, "src": "Unit 1 (Applications of Biology), Q58"}, {"topic": "Core concepts, genomics, ethics and biosafety", "sn": 59, "text": "Which of the following statements about biosafety levels (BSL) is correct?", "opts": ["BSL-1 facilities handle the most dangerous, lethal airborne pathogens known to science.", "The BSL ranking system goes from 1 to 4, with BSL-4 requiring maximum containment for highly dangerous and untreatable exotic agents.", "Every standard high school laboratory is fully certified to operate at BSL-3 configurations.", "Biosafety levels only apply to laboratories handling toxic chemical liquids, not living microbes."], "ans": "B", "steps": [["BSL runs from 1 (least risk) to 4 (highest risk)", "BSL-4 gives maximum containment"], ["{{A}} reverses the scale, {{C}} is false, {{D}} is false (BSL is about microbes)", "reject, so {{B}}"]], "note": "", "n": 57, "src": "Unit 1 (Applications of Biology), Q59"}, {"topic": "Core concepts, genomics, ethics and biosafety", "sn": 60, "text": "What is the name of the international agreement that governs the cross-border movement, transit, and handling of Living Modified Organisms (LMOs) resulting from modern biotechnology?", "opts": ["The Kyoto Protocol", "The Cartagena Protocol on Biosafety", "The Paris Accord", "The Geneva Convention"], "ans": "B", "steps": [["Cross-border movement of LMOs", "governed by the Cartagena Protocol on Biosafety"], ["Kyoto and Paris are about climate, Geneva is about war", "reject, so {{B}}"]], "note": "", "n": 58, "src": "Unit 1 (Applications of Biology), Q60"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 1, "text": "Which of the following components is present in the cell wall of Bacteria but completely absent in Archaea?", "opts": ["Chitin", "Peptidoglycan", "Pseudopeptidoglycan", "Lipopolysaccharide"], "ans": "B", "steps": [["True peptidoglycan is the hallmark of bacterial cell walls", "archaea lack it"], ["Chitin is fungal, pseudopeptidoglycan is archaeal, LPS is found only in Gram-negative bacteria (not all bacteria)", "reject, so {{B}}"]], "note": "", "n": 59, "src": "Unit 2 (Microorganisms), Q1"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 2, "text": "A student performs a Gram stain on a bacterial culture and observes pink/red rod-shaped cells under the microscope. How should these bacteria be classified?", "opts": ["Gram-positive bacilli", "Gram-negative bacilli", "Gram-positive cocci", "Gram-negative spirilla"], "ans": "B", "steps": [["Pink or red means the cells lost the crystal violet and kept the safranin counterstain", "Gram-negative"], ["Rod shape means bacilli; cocci are round and spirilla are spiral", "reject, so {{B}}"]], "note": "", "n": 60, "src": "Unit 2 (Microorganisms), Q2"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 3, "text": "What makes the cell wall of Gram-negative bacteria more complex than that of Gram-positive bacteria?", "opts": ["A much thicker layer of peptidoglycan", "The presence of teichoic acids", "An asymmetric outer membrane containing lipopolysaccharides (LPS)", "A thick capsule made of polypeptides"], "ans": "C", "steps": [["Gram-negative walls have a thin peptidoglycan layer plus an outer membrane with LPS", "that outer membrane adds the complexity"], ["{{A,B}} describe Gram-positive walls; {{D}} is a capsule, not part of the wall", "reject, so {{C}}"]], "note": "", "n": 61, "src": "Unit 2 (Microorganisms), Q3"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 4, "text": "During the Gram staining procedure, what would happen if a student forgot to apply the iodine (mordant) step?", "opts": ["All cells would appear purple.", "Gram-positive cells would lose the crystal violet and appear pink/red at the end.", "Gram-negative cells would resist decolorization and appear purple.", "The cells would melt due to poor chemical fixing."], "ans": "B", "steps": [["Iodine locks crystal violet inside the cell", "without it, alcohol washes the dye out of Gram-positive cells"], ["They then take up the safranin counterstain and look pink or red", "so {{B}}; {{A,C,D}} are not what happens"]], "note": "", "n": 62, "src": "Unit 2 (Microorganisms), Q4"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 5, "text": "What is the structural function of the bacterial endospore?", "opts": ["A specialized structure designed for rapid sexual reproduction", "A metabolic state allowing high rates of protein synthesis", "A highly resistant, dormant structure that protects genetic material under harsh conditions", "A capsule designed to help pathogenic bacteria stick to host tissues"], "ans": "C", "steps": [["Endospores form when conditions turn harsh", "they are dormant and resist heat, dryness and chemicals"], ["{{A}} is wrong (not reproduction), {{B}} is wrong (metabolism is near zero), {{D}} describes a capsule or fimbriae", "reject, so {{C}}"]], "note": "", "n": 63, "src": "Unit 2 (Microorganisms), Q5"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 6, "text": "Which prokaryotic structure is primarily responsible for mediating motility via rotational movement?", "opts": ["Fimbriae", "Pili", "Flagella", "Glycocalyx"], "ans": "C", "steps": [["A flagellum spins like a propeller", "this rotation moves the cell"], ["Fimbriae and pili attach or transfer DNA; the glycocalyx is a sticky coat", "reject, so {{C}}"]], "note": "", "n": 64, "src": "Unit 2 (Microorganisms), Q6"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 7, "text": "Hair-like surface appendages that allow bacteria to adhere to target host cells or surfaces are known as:", "opts": ["Flagella", "Axial filaments", "Fimbriae", "Inclusions"], "ans": "C", "steps": [["Short hair-like appendages used for attachment", "fimbriae"], ["Flagella and axial filaments are for movement; inclusions are storage granules inside the cell", "reject, so {{C}}"]], "note": "", "n": 65, "src": "Unit 2 (Microorganisms), Q7"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 8, "text": "What type of bacterial genetic recombination requires physical cell-to-cell contact through a sex pilus?", "opts": ["Transformation", "Conjugation", "Transduction", "Transposition"], "ans": "B", "steps": [["The sex pilus links two cells", "DNA (often a plasmid) is passed across, which is conjugation"], ["Transformation takes up naked DNA, transduction uses a phage, transposition is a jumping gene", "reject, so {{B}}"]], "note": "", "n": 66, "src": "Unit 2 (Microorganisms), Q8"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 9, "text": "In 1928, Frederick Griffith discovered that living, non-virulent bacteria could take up naked DNA from dead, virulent bacteria to become virulent. This horizontal gene transfer mechanism is called:", "opts": ["Transduction", "Conjugation", "Transformation", "Transfection"], "ans": "C", "steps": [["Uptake of naked DNA from the surroundings", "transformation (Griffith's experiment)"], ["Transduction needs a virus, conjugation needs contact, transfection is for eukaryotic cells", "reject, so {{C}}"]], "note": "", "n": 67, "src": "Unit 2 (Microorganisms), Q9"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 10, "text": "When a bacteriophage virus accidentally packages random host bacterial DNA into its capsid and delivers it to a new recipient bacterium, the process is called:", "opts": ["Conjugation", "Specialized transduction", "Generalized transduction", "Competence induction"], "ans": "C", "steps": [["A phage carries bacterial DNA to a new host", "that is transduction"], ["Random pieces mean generalized; specialized transduction carries only genes next to the prophage site", "reject, so {{C}}"]], "note": "", "n": 68, "src": "Unit 2 (Microorganisms), Q10"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 11, "text": "Plasmids that carry genes encoding enzymes capable of destroying or inactivating specific antibiotics are called:", "opts": ["F plasmids", "Virulence plasmids", "Metabolic plasmids", "R plasmids"], "ans": "D", "steps": [["R stands for resistance", "R plasmids carry genes that inactivate antibiotics"], ["F plasmids give fertility (sex pilus), virulence plasmids give toxins, metabolic plasmids give extra metabolic pathways", "reject, so {{D}}"]], "note": "", "n": 69, "src": "Unit 2 (Microorganisms), Q11"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 12, "text": "Bacteria that grow optimally at high temperatures between 50°C and 80°C (such as those in geothermal hot springs) are classified as:", "opts": ["Psychrophilic", "Mesophilic", "Thermophilic", "Halophilic"], "ans": "C", "steps": [["Thermo = heat", "thermophiles prefer 50 to 80 degrees C"], ["Psychro = cold, meso = moderate, halo = salt", "reject, so {{C}}"]], "note": "", "n": 70, "src": "Unit 2 (Microorganisms), Q12"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 13, "text": "An organism that uses light as its energy source and organic compounds (like carbohydrates or alcohols) as its carbon source is a:", "opts": ["Photoautotroph", "Photoheterotroph", "Chemoautotroph", "Chemoheterotroph"], "ans": "B", "steps": [["Energy source light means photo", "organic carbon source means hetero, so photoheterotroph"], ["Photoautotrophs use CO2, and chemo- types use chemical energy", "reject, so {{B}}"]], "note": "", "n": 71, "src": "Unit 2 (Microorganisms), Q13"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 14, "text": "Why are obligate anaerobes killed when exposed to atmospheric oxygen?", "opts": ["They lack enzymes like superoxide dismutase (SOD) and catalase to neutralize toxic oxygen radicals.", "Oxygen physically dissolves their peptidoglycan layer.", "Oxygen blocks their ability to carry out glycolysis.", "They lack a cell membrane capable of diffusing gases."], "ans": "A", "steps": [["Oxygen makes toxic radicals (superoxide, peroxide)", "SOD and catalase destroy them, and obligate anaerobes lack both"], ["{{B,C,D}} are not true", "reject, so {{A}}"]], "note": "", "n": 72, "src": "Unit 2 (Microorganisms), Q14"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 15, "text": "What is the exact region in a prokaryotic cell where the single, circular chromosome is localized?", "opts": ["Nucleus", "Nucleolus", "Nucleoid", "Periplasm"], "ans": "C", "steps": [["Prokaryotes have no membrane-bound nucleus", "the chromosome sits in an irregular region called the nucleoid"], ["Nucleus and nucleolus are eukaryotic; the periplasm lies between the membranes of Gram-negative cells", "reject, so {{C}}"]], "note": "", "n": 73, "src": "Unit 2 (Microorganisms), Q15"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 16, "text": "Which of the following is true regarding the plasma membrane of organisms in the domain Archaea?", "opts": ["It contains ester linkages between glycerol and unbranched fatty acids.", "It contains ether linkages between glycerol and branched hydrocarbons (isoprenoids).", "It is always a phospholipid bilayer identical to human membranes.", "It completely lacks any transport proteins."], "ans": "B", "steps": [["Archaeal membrane lipids use ether linkages and branched isoprenoid chains", "this suits extreme conditions"], ["{{A}} describes bacteria and eukaryotes; {{C,D}} are false", "reject, so {{B}}"]], "note": "", "n": 74, "src": "Unit 2 (Microorganisms), Q16"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 17, "text": "Methanogenic archaea reduce carbon dioxide into methane gas under which environmental condition?", "opts": ["Highly oxygenated aquatic zones", "Aerobic topsoil layers", "Strict anaerobic environments, such as swamp sediments or animal rumens", "Glacial ice sheets"], "ans": "C", "steps": [["Methanogens are strict anaerobes", "they live where oxygen is absent (swamp mud, rumen, guts)"], ["Oxygenated water and topsoil kill them; ice is not their habitat", "reject, so {{C}}"]], "note": "", "n": 75, "src": "Unit 2 (Microorganisms), Q17"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 18, "text": "Halophilic archaea require high concentrations of which substance to sustain cell growth and wall integrity?", "opts": ["Heavy metals", "Sodium chloride (Salt)", "Sulfuric acid", "Liquid nitrogen"], "ans": "B", "steps": [["Halo = salt", "halophiles need high NaCl to grow and keep their walls intact"], ["Heavy metals, sulfuric acid and liquid nitrogen are not growth requirements", "reject, so {{B}}"]], "note": "", "n": 76, "src": "Unit 2 (Microorganisms), Q18"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 19, "text": "What shape description corresponds to bacteria clustered together in sheet-like or grape-like aggregates?", "opts": ["Streptococci", "Staphylococci", "Diplococci", "Tetrads"], "ans": "B", "steps": [["Cocci dividing in random planes form irregular, grape-like clusters", "staphylococci"], ["Streptococci form chains, diplococci form pairs, tetrads form groups of four", "reject, so {{B}}"]], "note": "\"Sheet-like\" is loosely worded; the grape-like clusters point to staphylococci.", "n": 77, "src": "Unit 2 (Microorganisms), Q19"}, {"topic": "Bacteria and archaea: structure, classification and genetics", "sn": 20, "text": "The invaginations of the plasma membrane in some bacteria that were historically thought to assist in cell division and respiration are called:", "opts": ["Ribosomes", "Mesosomes", "Inclusion bodies", "Carboxysomes"], "ans": "B", "steps": [["Folds of the plasma membrane thought to aid division and respiration", "mesosomes"], ["Ribosomes make protein, inclusion bodies store materials, carboxysomes hold CO2-fixing enzymes", "reject, so {{B}}"]], "note": "Mesosomes are now thought to be artifacts of specimen preparation.", "n": 78, "src": "Unit 2 (Microorganisms), Q20"}, {"topic": "Viruses and viral pathogenesis", "sn": 21, "text": "Why are viruses universally considered acellular infectious particles rather than living organisms?", "opts": ["They lack generic code like DNA or RNA.", "They cannot evolve or mutate over time.", "They do not possess a cellular structure, cytoplasm, or an independent metabolism.", "They are larger than the smallest known bacteria."], "ans": "C", "steps": [["Viruses have no cell, no cytoplasm and no metabolism of their own", "they only replicate inside a host"], ["{{A,B}} are false (they have DNA or RNA and they evolve); {{D}} is false (they are smaller)", "reject, so {{C}}"]], "note": "", "n": 79, "src": "Unit 2 (Microorganisms), Q21"}, {"topic": "Viruses and viral pathogenesis", "sn": 22, "text": "The protein shell that encloses and protects the nucleic acid core of a virus is called the:", "opts": ["Envelope", "Capsid", "Capsomere", "Matrix"], "ans": "B", "steps": [["The protein coat around the genome", "the capsid"], ["The envelope is a lipid layer, a capsomere is one subunit of the capsid", "reject, so {{B}}"]], "note": "", "n": 80, "src": "Unit 2 (Microorganisms), Q22"}, {"topic": "Viruses and viral pathogenesis", "sn": 23, "text": "Where do enveloped viruses typically acquire their outer lipid envelope layer?", "opts": ["They synthesize it from scratch using viral metabolic pathways.", "They steal it from the host cell's plasma membrane or nuclear membrane during budding.", "They absorb it from environmental organic matter.", "They extract it from the bacterial cell wall via lysis."], "ans": "B", "steps": [["Viruses have no metabolism to make lipids", "they bud out and wrap themselves in host membrane"], ["{{A,C,D}} are not how envelopes form", "reject, so {{B}}"]], "note": "", "n": 81, "src": "Unit 2 (Microorganisms), Q23"}, {"topic": "Viruses and viral pathogenesis", "sn": 24, "text": "The fundamental subunits that form the structure of a viral capsid are called:", "opts": ["Spikes", "Nucleosomes", "Capsomeres", "Virions"], "ans": "C", "steps": [["A capsid is built from repeating protein subunits", "capsomeres"], ["Spikes are surface proteins, nucleosomes are DNA-histone units, a virion is the whole virus particle", "reject, so {{C}}"]], "note": "", "n": 82, "src": "Unit 2 (Microorganisms), Q24"}, {"topic": "Viruses and viral pathogenesis", "sn": 25, "text": "A virus that specifically infects and replicates inside bacterial cells is called a:", "opts": ["Viroid", "Prion", "Bacteriophage", "Retrovirus"], "ans": "C", "steps": [["Phage means \"eater\"", "a bacteriophage infects bacteria"], ["Viroids are bare RNA, prions are proteins, retroviruses infect animal cells", "reject, so {{C}}"]], "note": "", "n": 83, "src": "Unit 2 (Microorganisms), Q25"}, {"topic": "Viruses and viral pathogenesis", "sn": 26, "text": "Which step in a viral replication cycle involves the binding of viral surface proteins or spikes to specific receptor molecules on the host cell membrane?", "opts": ["Penetration", "Adsorption (Attachment)", "Uncoating", "Biosynthesis"], "ans": "B", "steps": [["The first step is binding of spikes to host receptors", "adsorption (attachment)"], ["Penetration is entry, uncoating releases the genome, biosynthesis makes viral parts", "reject, so {{B}}"]], "note": "", "n": 84, "src": "Unit 2 (Microorganisms), Q26"}, {"topic": "Viruses and viral pathogenesis", "sn": 27, "text": "During the lytic cycle of a bacteriophage, what happens immediately following the assembly of newly synthesized viral parts?", "opts": ["The viral genome integrates into the host chromosome.", "The host cell splits open (lyses) to release mature viral progeny.", "The phage enters a long-term state of dormancy.", "The host cell begins binary fission."], "ans": "B", "steps": [["Lytic order: attach, enter, make parts, assemble, release", "after assembly the cell bursts (lysis)"], ["Integration and dormancy belong to the lysogenic cycle; a lysed cell cannot divide", "reject, so {{B}}"]], "note": "", "n": 85, "src": "Unit 2 (Microorganisms), Q27"}, {"topic": "Viruses and viral pathogenesis", "sn": 28, "text": "What is an integrated, dormant viral genome hidden inside a host bacterium's chromosome called during the lysogenic cycle?", "opts": ["Provirus", "Prophage", "Viroid", "Capsid core"], "ans": "B", "steps": [["Phage DNA integrated into a bacterial chromosome", "a prophage"], ["\"Provirus\" is the term for animal viruses such as HIV; a viroid is a bare RNA", "reject, so {{B}}"]], "note": "", "n": 86, "src": "Unit 2 (Microorganisms), Q28"}, {"topic": "Viruses and viral pathogenesis", "sn": 29, "text": "What event triggers a lysogenic bacteriophage to exit the lysogenic cycle and enter the destructive lytic cycle?", "opts": ["Spontaneous binary fission", "Environmental stress or UV radiation causing induction", "High nutrient availability in the medium", "Antibiotic treatment of the host cell."], "ans": "B", "steps": [["Stress or UV damages the host", "the prophage is induced to leave and turns lytic"], ["{{A,C}} favour staying lysogenic (the prophage copies with the host); {{D}} is not the standard trigger", "reject, so {{B}}"]], "note": "", "n": 87, "src": "Unit 2 (Microorganisms), Q29"}, {"topic": "Viruses and viral pathogenesis", "sn": 30, "text": "Human Immunodeficiency Virus (HIV) belongs to which specialized group of viruses?", "opts": ["Non-enveloped DNA viruses", "Double-stranded RNA reoviruses", "Retroviruses", "Invertebrate baculoviruses"], "ans": "C", "steps": [["HIV has an RNA genome and reverse transcriptase", "it is a retrovirus"], ["{{A,B,D}} do not match HIV", "reject, so {{C}}"]], "note": "", "n": 88, "src": "Unit 2 (Microorganisms), Q30"}, {"topic": "Viruses and viral pathogenesis", "sn": 31, "text": "What is the role of the enzyme reverse transcriptase during HIV replication?", "opts": ["It translates viral RNA directly into functional structural proteins.", "It transcribes single-stranded viral RNA into double-stranded DNA.", "It cleaves long viral polyproteins into smaller active units.", "It stitches viral DNA into the human host cell chromosome."], "ans": "B", "steps": [["Reverse transcription = RNA to DNA", "it makes double-stranded DNA from viral RNA"], ["{{A}} is the ribosome, {{C}} is protease, {{D}} is integrase", "reject, so {{B}}"]], "note": "", "n": 89, "src": "Unit 2 (Microorganisms), Q31"}, {"topic": "Viruses and viral pathogenesis", "sn": 32, "text": "Which specific human immune system cells are preferentially targeted and destroyed by HIV?", "opts": ["B lymphocytes", "Cytotoxic T cells", "Helper T cells (CD4+ T cells)", "Natural Killer (NK) cells"], "ans": "C", "steps": [["HIV binds the CD4 receptor", "helper T cells are infected and destroyed, which weakens the whole immune response"], ["B cells, cytotoxic T cells and NK cells lack CD4 as the main target", "reject, so {{C}}"]], "note": "", "n": 90, "src": "Unit 2 (Microorganisms), Q32"}, {"topic": "Viruses and viral pathogenesis", "sn": 33, "text": "Which viral enzyme is responsible for integrating the synthesized viral DNA into the host cell's nuclear DNA?", "opts": ["Reverse transcriptase", "Integrase", "Protease", "RNA polymerase"], "ans": "B", "steps": [["Integrating viral DNA into the host chromosome", "integrase"], ["Reverse transcriptase makes the DNA, protease cuts polyproteins, RNA polymerase makes RNA", "reject, so {{B}}"]], "note": "", "n": 91, "src": "Unit 2 (Microorganisms), Q33"}, {"topic": "Viruses and viral pathogenesis", "sn": 34, "text": "Infectious agents that cause disease but are composed entirely of misfolded protein molecules with no nucleic acids are:", "opts": ["Viroids", "Prions", "Virions", "Satellites"], "ans": "B", "steps": [["Infectious protein with no nucleic acid", "prions (e.g., mad cow disease)"], ["Viroids are bare RNA, a virion is a complete virus, satellites need a helper virus", "reject, so {{B}}"]], "note": "", "n": 92, "src": "Unit 2 (Microorganisms), Q34"}, {"topic": "Viruses and viral pathogenesis", "sn": 35, "text": "Plant diseases like potato spindle tuber disease are caused by small, naked, single-stranded circular RNA molecules lacking a protein coat. These agents are called:", "opts": ["Prions", "Bacteriophages", "Viroids", "Core capsids"], "ans": "C", "steps": [["Small naked circular RNA infecting plants", "viroids"], ["Prions are proteins, bacteriophages infect bacteria, \"core capsids\" have a protein coat", "reject, so {{C}}"]], "note": "", "n": 93, "src": "Unit 2 (Microorganisms), Q35"}, {"topic": "Viruses and viral pathogenesis", "sn": 36, "text": "Which viral morphology is characterized by a long, rigid, or flexible rod-like shape where capsomeres are arranged in a helical pattern around the nucleic acid?", "opts": ["Polyhedral", "Complex", "Enveloped spheres", "Helical"], "ans": "D", "steps": [["Rod shape with capsomeres wound in a spiral", "helical (e.g., tobacco mosaic virus)"], ["Polyhedral is many-sided, complex has a head and tail, enveloped spheres are round", "reject, so {{D}}"]], "note": "", "n": 94, "src": "Unit 2 (Microorganisms), Q36"}, {"topic": "Viruses and viral pathogenesis", "sn": 37, "text": "T-even bacteriophages (like T4) exhibit a 'complex' viral shape. This means they possess:", "opts": ["Only a simple lipid sphere", "An icosahedral head attached to a helical tail assembly with tail fibers", "A completely fluid shapeless envelope", "Linear RNA without a capsid coat"], "ans": "B", "steps": [["Complex means more than one shape in the same particle", "T4 has an icosahedral head, a helical tail and tail fibers"], ["{{A,C,D}} do not describe T4 (it has a capsid and DNA)", "reject, so {{B}}"]], "note": "", "n": 95, "src": "Unit 2 (Microorganisms), Q37"}, {"topic": "Viruses and viral pathogenesis", "sn": 38, "text": "What occurs during the 'uncoating' step of an animal virus replication cycle?", "opts": ["The virus loses its tail fibers during assembly.", "The viral envelope fuses with the outer environment.", "The viral capsid is enzymatically removed, releasing the viral nucleic acid into the cytoplasm.", "The host cell sheds its receptors to prevent further infection."], "ans": "C", "steps": [["Uncoating happens after entry", "the capsid is stripped off and the nucleic acid is released"], ["{{A,B,D}} are not uncoating", "reject, so {{C}}"]], "note": "", "n": 96, "src": "Unit 2 (Microorganisms), Q38"}, {"topic": "Viruses and viral pathogenesis", "sn": 39, "text": "Budding is a mechanism of viral release that allows the virus to leave the cell without doing what immediately?", "opts": ["Replicating its genetic material", "Damaging host protein synthesis", "Rupturing or lysing the host cell", "Acquiring a membrane layer"], "ans": "C", "steps": [["In budding the virus pushes out through the membrane", "the host cell survives for a while instead of bursting"], ["Budding does acquire a membrane ({{D}} is the opposite); {{A,B}} are not what budding avoids", "reject, so {{C}}"]], "note": "", "n": 97, "src": "Unit 2 (Microorganisms), Q39"}, {"topic": "Viruses and viral pathogenesis", "sn": 40, "text": "Why are traditional antibiotics completely useless for treating viral illnesses like influenza or the common cold?", "opts": ["Viral capsids are too thick for antibiotics to cross.", "Viruses lack cellular targets like peptidoglycan walls, 70S ribosomes, or bacterial metabolic enzymes that antibiotics disrupt.", "Viruses degrade antibiotics into energy sources.", "Antibiotics only target eukaryotic structures."], "ans": "B", "steps": [["Antibiotics attack bacterial structures (walls, 70S ribosomes, enzymes)", "viruses have none of these"], ["{{A,C,D}} are false", "reject, so {{B}}"]], "note": "", "n": 98, "src": "Unit 2 (Microorganisms), Q40"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 41, "text": "The vast majority of fungi have cell walls composed of which tough polysaccharide?", "opts": ["Cellulose", "Peptidoglycan", "Chitin", "Pectin"], "ans": "C", "steps": [["Fungal walls are made of chitin", "the same material as insect exoskeletons"], ["Cellulose is the plant wall, peptidoglycan the bacterial wall, pectin a plant wall component", "reject, so {{C}}"]], "note": "", "n": 99, "src": "Unit 2 (Microorganisms), Q41"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 42, "text": "Unicellular fungi that typically reproduce asexually by an asymmetric division process called 'budding' are:", "opts": ["Molds", "Yeasts", "Mushrooms", "Smuts"], "ans": "B", "steps": [["Single-celled fungi that bud", "yeasts"], ["Molds and mushrooms are multicellular, smuts are plant-parasitic fungi", "reject, so {{B}}"]], "note": "", "n": 100, "src": "Unit 2 (Microorganisms), Q42"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 43, "text": "The microscopic thread-like filaments that form the vegetative body (mycelium) of a multicellular fungus are:", "opts": ["Hyphae", "Spores", "Conidia", "Flagella"], "ans": "A", "steps": [["Threads that make up the mycelium", "hyphae"], ["Spores and conidia are reproductive cells; most fungi have no flagella", "reject, so {{A}}"]], "note": "", "n": 101, "src": "Unit 2 (Microorganisms), Q43"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 44, "text": "Fungi that obtain their nutrition by absorbing organic matter from dead, decaying organisms are ecologically classified as:", "opts": ["Obligate parasites", "Saprophytes (Saprobes)", "Mutualistic symbionts", "Photoautotrophs"], "ans": "B", "steps": [["Feeding on dead, decaying matter", "saprophytes (saprobes)"], ["Parasites feed on living hosts, symbionts share benefits, photoautotrophs photosynthesize", "reject, so {{B}}"]], "note": "", "n": 102, "src": "Unit 2 (Microorganisms), Q44"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 45, "text": "Which protozoan group uses short, hair-like projections covering the cell surface for both locomotion and moving food particles into their cytostome?", "opts": ["Amoeboid protozoa (Sarcodina)", "Flagellates (Mastigophora)", "Ciliates (Ciliophora)", "Sporozoans (Apicomplexa)"], "ans": "C", "steps": [["Short hair-like projections covering the cell are cilia", "the group is the ciliates (e.g., Paramecium)"], ["Amoebae use pseudopodia, flagellates use flagella, sporozoans have no locomotor structures", "reject, so {{C}}"]], "note": "", "n": 103, "src": "Unit 2 (Microorganisms), Q45"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 46, "text": "The causative agent of malaria, Plasmodium, belongs to which group of protozoa due to its lack of specialized locomotor structures and complex lifecycle?", "opts": ["Ciliates", "Amoebae", "Apicomplexans (Sporozoans)", "Dinoflagellates"], "ans": "C", "steps": [["Plasmodium has no locomotor organelles in its main stages and a complex life cycle", "apicomplexan (sporozoan)"], ["Ciliates, amoebae and dinoflagellates move by cilia, pseudopodia and flagella", "reject, so {{C}}"]], "note": "", "n": 104, "src": "Unit 2 (Microorganisms), Q46"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 47, "text": "Which specific group of soil bacteria are responsible for performing biological nitrogen fixation, converting atmospheric N2 gas into ammonia (NH3)?", "opts": ["Denitrifying bacteria", "Nitrifying bacteria", "Nitrogen-fixing bacteria (e.g., Rhizobium, Azotobacter)", "Ammonifying fungi"], "ans": "C", "steps": [["N2 to NH3 is nitrogen fixation", "done by Rhizobium, Azotobacter and similar bacteria"], ["Denitrifiers return N2 to the air, nitrifiers make nitrate, ammonifiers release ammonia from dead matter", "reject, so {{C}}"]], "note": "", "n": 105, "src": "Unit 2 (Microorganisms), Q47"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 48, "text": "In filamentous cyanobacteria, what are the specialized, thick-walled, oxygen-depleted cells where nitrogen fixation is isolated to protect the nitrogenase enzyme?", "opts": ["Akinetes", "Heterocysts", "Endospores", "Hormogonia"], "ans": "B", "steps": [["Nitrogenase is destroyed by oxygen", "heterocysts are thick-walled cells with little oxygen where fixation happens"], ["Akinetes are resting cells, endospores are dormant forms, hormogonia are motile fragments", "reject, so {{B}}"]], "note": "", "n": 106, "src": "Unit 2 (Microorganisms), Q48"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 49, "text": "What is the process where bacteria oxidize ammonia (NH3) first into nitrites (NO2-) and then into nitrates (NO3-)?", "opts": ["Nitrogen fixation", "Denitrification", "Nitrification", "Ammonification"], "ans": "C", "steps": [["NH3 to NO2- to NO3- is oxidation", "nitrification"], ["Fixation makes NH3, denitrification makes N2 gas, ammonification releases NH3", "reject, so {{C}}"]], "note": "", "n": 107, "src": "Unit 2 (Microorganisms), Q49"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 53, "text": "Commercial antibiotics like penicillin are naturally produced by which group of microorganisms to kill competing bacteria?", "opts": ["Viruses", "Archaea", "Specific filamentous fungi and actinomycete bacteria", "Protozoa"], "ans": "C", "steps": [["Antibiotics are made to kill competitors", "mainly by filamentous fungi (Penicillium) and actinomycetes (Streptomyces)"], ["Viruses, archaea and protozoa are not antibiotic sources", "reject, so {{C}}"]], "note": "", "n": 108, "src": "Unit 2 (Microorganisms), Q53"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 54, "text": "In recombinant DNA technology, what is the primary function of using a bacterial plasmid vector?", "opts": ["To act as a source of energy for replication enzymes", "To serve as a vehicle that carries a foreign gene of interest into a host cell for cloning and expression", "To digest the host cell wall during insertion", "To serve as an antibody variant"], "ans": "B", "steps": [["A plasmid vector is a carrier", "it takes the foreign gene into the host cell for cloning and expression"], ["{{A,C,D}} are not vector roles", "reject, so {{B}}"]], "note": "", "n": 109, "src": "Unit 2 (Microorganisms), Q54"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 55, "text": "Which organic acid is produced industrially by fermenting dairy products or starches using Lactobacillus species?", "opts": ["Citric acid", "Acetic acid", "Lactic acid", "Formic acid"], "ans": "C", "steps": [["Lactobacillus ferments sugars to lactic acid", "used in yogurt, cheese and preservation"], ["Citric acid comes from Aspergillus niger, acetic acid from Acetobacter", "reject, so {{C}}"]], "note": "", "n": 110, "src": "Unit 2 (Microorganisms), Q55"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 56, "text": "What is the defining characteristic of a mutualistic symbiotic relationship involving microorganisms?", "opts": ["One partner benefits while the other is severely harmed.", "Both interacting species derive biological benefits from the association.", "One partner benefits while the other is completely unaffected.", "Both species compete until one is driven to extinction."], "ans": "B", "steps": [["Mutualism means both partners gain", "for example lichens and mycorrhizae"], ["{{A}} is parasitism, {{C}} is commensalism, {{D}} is competition", "reject, so {{B}}"]], "note": "", "n": 111, "src": "Unit 2 (Microorganisms), Q56"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 57, "text": "Lichens represent a highly integrated mutualistic symbiotic association between which two organisms?", "opts": ["A fungus and a plant root", "A protozoan and a bacterium", "A fungus and a photosynthetic partner (algae or cyanobacteria)", "A virus and a leaf surface"], "ans": "C", "steps": [["Lichen = fungus plus alga or cyanobacterium", "the fungus protects and the partner photosynthesizes"], ["{{A}} is mycorrhiza; {{B,D}} are not lichens", "reject, so {{C}}"]], "note": "", "n": 112, "src": "Unit 2 (Microorganisms), Q57"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 58, "text": "What is the term for the mutualistic association formed between specific soil fungi and the roots of vascular plants?", "opts": ["Lichen", "Mycorrhizae", "Rhizobium nodule", "Endospores"], "ans": "B", "steps": [["Fungus plus plant root", "mycorrhizae"], ["A lichen has no roots, a Rhizobium nodule involves bacteria, endospores are dormant bacterial cells", "reject, so {{B}}"]], "note": "", "n": 113, "src": "Unit 2 (Microorganisms), Q58"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 59, "text": "Which bacterial toxin type is composed of lipopolysaccharides (LPS) that form an integral part of the outer membrane of Gram-negative cell walls and are released only upon cell death/lysis?", "opts": ["Exotoxins", "Endotoxins", "Anatoxins", "Neurotoxins"], "ans": "B", "steps": [["LPS in the outer membrane, released when the cell dies", "endotoxin"], ["Exotoxins are secreted proteins from live cells; anatoxins are inactivated toxins used in vaccines; neurotoxins attack nerves", "reject, so {{B}}"]], "note": "", "n": 114, "src": "Unit 2 (Microorganisms), Q59"}, {"topic": "Fungi, protists, ecology and biotechnology", "sn": 60, "text": "In traditional Ethiopian food preparation, the souring of teff batter for injera making or the production of ergo (sour milk) is primarily driven by which microorganisms?", "opts": ["Methanogenic Archaea", "Lactic Acid Bacteria (LAB) and native yeasts", "Sulfur-reducing bacteria", "Filamentous water molds"], "ans": "B", "steps": [["Souring means acid production from sugars", "lactic acid bacteria (with native yeasts) do this in fermenting teff and milk"], ["Methanogens, sulfur-reducers and water molds are not involved", "reject, so {{B}}"]], "note": "", "n": 115, "src": "Unit 2 (Microorganisms), Q60"}];
